package com.flowforge.infrastructure.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.Instant;
import java.util.Objects;
import java.util.UUID;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

/**
 * Webhook registration of one workflow. The public {@code webhookId} and the secret are generated by the server once
 * and kept for the life of the workflow (rotate the secret explicitly). Settings are copied from the trigger node on
 * every sync so the webhook endpoint never parses workflow definitions.
 *
 * <p>The secret is stored either encrypted ({@code secretKeyId}, {@code secretNonce}, {@code secretCiphertext}; normal
 * case) or, only on servers without a credential keyring and for rows from before Module 12, as legacy plaintext
 * ({@code secret}). Exactly one form is set (database check). Use {@code WebhookSecretStore} to read or write it.
 */
@Entity
@Table(name = "webhook_triggers")
public class WebhookTriggerEntity {

    @Id
    @Column(name = "workflow_id")
    private UUID workflowId;

    @Column(name = "webhook_id", nullable = false, updatable = false, length = 64)
    private String webhookId;

    @Column(name = "node_id", nullable = false, length = 64)
    private String nodeId;

    @Column(name = "http_method", nullable = false, length = 10)
    private String httpMethod;

    @Column(nullable = false, length = 20)
    private String authentication;

    @Column(name = "input_mode", nullable = false, length = 20)
    private String inputMode;

    /** Legacy plaintext; null once encrypted. */
    @Column(length = 128)
    private String secret;

    @Column(name = "secret_key_id", length = 64)
    private String secretKeyId;

    @Column(name = "secret_nonce")
    private byte[] secretNonce;

    @Column(name = "secret_ciphertext")
    private byte[] secretCiphertext;

    @Column(nullable = false)
    private boolean active;

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    @Column(name = "lock_version", nullable = false)
    private Long lockVersion;

    protected WebhookTriggerEntity() {
    }

    /** Set the secret with {@link #sealSecret} or {@link #storePlaintextSecret} before saving. */
    public WebhookTriggerEntity(UUID workflowId, String webhookId) {
        this.workflowId = Objects.requireNonNull(workflowId);
        this.webhookId = Objects.requireNonNull(webhookId);
    }

    public void configure(String nodeId, String httpMethod, String authentication, String inputMode) {
        this.nodeId = nodeId;
        this.httpMethod = httpMethod;
        this.authentication = authentication;
        this.inputMode = inputMode;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    public void sealSecret(String keyId, byte[] nonce, byte[] ciphertext) {
        this.secret = null;
        this.secretKeyId = Objects.requireNonNull(keyId);
        this.secretNonce = nonce.clone();
        this.secretCiphertext = ciphertext.clone();
    }

    /** Legacy mode (no keyring configured). */
    public void storePlaintextSecret(String plaintext) {
        this.secret = Objects.requireNonNull(plaintext);
        this.secretKeyId = null;
        this.secretNonce = null;
        this.secretCiphertext = null;
    }

    public boolean isSecretEncrypted() {
        return secretCiphertext != null;
    }

    public UUID getWorkflowId() {
        return workflowId;
    }

    public String getWebhookId() {
        return webhookId;
    }

    public String getNodeId() {
        return nodeId;
    }

    public String getHttpMethod() {
        return httpMethod;
    }

    public String getAuthentication() {
        return authentication;
    }

    public String getInputMode() {
        return inputMode;
    }

    /** Legacy plaintext secret, or null when encrypted. */
    public String getPlaintextSecret() {
        return secret;
    }

    public String getSecretKeyId() {
        return secretKeyId;
    }

    public byte[] getSecretNonce() {
        return secretNonce == null ? null : secretNonce.clone();
    }

    public byte[] getSecretCiphertext() {
        return secretCiphertext == null ? null : secretCiphertext.clone();
    }

    public boolean isActive() {
        return active;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }
}
